from collections import deque
from math import gcd


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("Invalid start bucket")

    if goal > max(bucket_one, bucket_two):
        raise ValueError("No solution possible")
    if goal % gcd(bucket_one, bucket_two) != 0:
        raise ValueError("No solution possible")

    start_is_one = start_bucket == "one"

    def is_forbidden(a, b):
        # After any action, the starting bucket may not be empty
        # while the other bucket is full.
        if start_is_one:
            return a == 0 and b == bucket_two
        return b == 0 and a == bucket_one

    def neighbors(a, b):
        yield bucket_one, b  # fill bucket one
        yield a, bucket_two  # fill bucket two
        yield 0, b  # empty bucket one
        yield a, 0  # empty bucket two
        pour = min(a, bucket_two - b)
        yield a - pour, b + pour  # pour one into two
        pour = min(b, bucket_one - a)
        yield a + pour, b - pour  # pour two into one

    # The first action must be filling the starting bucket.
    start = (bucket_one, 0) if start_is_one else (0, bucket_two)
    if start[0] == goal:
        return (1, "one", start[1])
    if start[1] == goal:
        return (1, "two", start[0])

    queue = deque([(start, 1)])
    seen = {start}
    while queue:
        (a, b), moves = queue.popleft()
        for na, nb in neighbors(a, b):
            if (na, nb) in seen or is_forbidden(na, nb):
                continue
            if na == goal:
                return (moves + 1, "one", nb)
            if nb == goal:
                return (moves + 1, "two", na)
            seen.add((na, nb))
            queue.append(((na, nb), moves + 1))

    raise ValueError("No solution possible")
